const shareDirectory = /^cooking-share-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const maxCopies = 8;
const readGraceMs = 60_000;

/** Prune only expired directories generated by the cooking share controls. */
export function pruneExchangeShares(directories, now, completionTime) {
  let retained = 0;
  for (const directory of directories) {
    if (!shareDirectory.test(directory.name)) continue;
    const completedAt = completionTime(directory);
    if (Number.isFinite(completedAt) && completedAt > 0 && now - completedAt >= readGraceMs) directory.delete();
    else retained++;
  }
  if (retained >= maxCopies) throw Error('Cooking share cache is full. Recent or unconfirmed copies are still protected.');
}
